#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxMedianSum(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        int k = n / 3;
        long long ans = 0;
        for (int i = 0; i < k; ++i) {
            ans += nums[n - 2 - 2 * i];
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long maxMedianSum(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int k = n / 3;
        long ans = 0;
        for (int i = 0; i < k; i++) {
            ans += nums[n - 2 - 2 * i];
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var maxMedianSum = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const k = Math.floor(n / 3);
    let ans = 0;
    for (let i = 0; i < k; i++) {
        ans += nums[n - 2 - 2 * i];
    }
    return ans;
};
